package com.user.pdfservice.model.entity;

import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.mapping.Document;

import java.time.LocalDateTime;

@Document(collection = "settings")
public class GlobalSettings {

    @Id
    private String id = "global_settings";

    // When true, data processed/generated by normal users is stored in MongoDB
    private boolean storeUserDataEnabled = false;

    private LocalDateTime updatedAt = LocalDateTime.now();

    private String updatedBy;

    public GlobalSettings() {}

    public GlobalSettings(boolean storeUserDataEnabled, String updatedBy) {
        this.id = "global_settings";
        this.storeUserDataEnabled = storeUserDataEnabled;
        this.updatedAt = LocalDateTime.now();
        this.updatedBy = updatedBy;
    }

    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = id;
    }

    public boolean isStoreUserDataEnabled() {
        return storeUserDataEnabled;
    }

    public void setStoreUserDataEnabled(boolean storeUserDataEnabled) {
        this.storeUserDataEnabled = storeUserDataEnabled;
    }

    public LocalDateTime getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(LocalDateTime updatedAt) {
        this.updatedAt = updatedAt;
    }

    public String getUpdatedBy() {
        return updatedBy;
    }

    public void setUpdatedBy(String updatedBy) {
        this.updatedBy = updatedBy;
    }
}

